"U pronájmu od nás nedostanete <g0>autopůjčovnu</g0> s denním tarifem, ale flexibilní <g1>konstrukci s měsíčním poplatkem, od minimální doby {1} měsíců</g1>: vybrané modely ⟨M1⟩ jsou k dispozici i k dlouhodobému užívání přes rok. Pokud chcete kupovat, každý z <g2>našich vozů na prodej</g2> je prověřený, zkontrolovaný na místě a přichází s <g3>odpovědností za vady {2} rok</g3>. A pokud přesně víte, co hledáte, dovezeme vám vůz z celého německého trhu: <g4>dovoz vozu z Německa</g4> včetně přepravy, registrace a kompletního vyřízení — vy jen převezmete klíč.": [
"When you rent from us, you don't get a <g0>car rental company</g0> with a daily fee, but a flexible <g1>monthly-fee arrangement with a minimum term of {1} months</g1>: selected ⟨M1⟩ models are available for long-term use, even for more than a year. If you would like to buy, each of <g2>our cars for sale</g2> is vetted, inspected on site and comes with a <g3>{2}-year liability for defects</g3>. And if you know exactly what you are looking for, we will import it for you from the entire German market: <g4>car import from Germany</g4> with transport, registration and all the paperwork — you just collect the keys.",
"Bei uns mieten Sie nicht bei einer <g0>Autovermietung</g0> mit Tagesgebühr, sondern in einem flexiblen <g1>Modell mit Monatsgebühr und einer Mindestdauer von {1} Monaten</g1>: Ausgewählte ⟨M1⟩ Modelle stehen zur langfristigen Nutzung bereit, auch für mehr als ein Jahr. Möchten Sie kaufen, ist jedes <g2>unserer Autos zum Verkauf</g2> geprüft, vor Ort kontrolliert und kommt mit <g3>{2} Jahr Mängelhaftung</g3>. Und wenn Sie genau wissen, was Sie suchen, importieren wir es aus dem gesamten deutschen Markt: <g4>Autoimport aus Deutschland</g4> mit Transport, Zulassung und allen Formalitäten — Sie übernehmen nur die Schlüssel."
],
"Nejvýhodnější měsíční poplatek začíná od {1} €/měsíc bez DPH (⟨M1⟩), naše prémiová ⟨M2⟩ jsou dostupná od {2} €/měsíc bez DPH; konkrétní cena závisí na modelu, délce pronájmu a měsíčním limitu km. Aktuální <g0>vozy k pronájmu najdete zde</g0>, pro nabídku nám zavolejte: <g1>+{3}</g1>.": [
"The most affordable monthly payment starts from {1} €/month excl. VAT (⟨M1⟩), our premium ⟨M2⟩ models are available from {2} €/month excl. VAT; the exact price depends on the model, the rental period and the monthly km limit. You can <g0>find the current cars for rent here</g0>; for an offer, call us: <g1>+{3}</g1>.",
"Die günstigste Monatsrate beginnt bei {1} €/Monat ohne MwSt. (⟨M1⟩), unsere Premium-⟨M2⟩ sind ab {2} €/Monat ohne MwSt. erhältlich; der konkrete Preis hängt vom Modell, der Mietdauer und dem monatlichen km-Limit ab. Die aktuellen <g0>Mietautos finden Sie hier</g0>, für ein Angebot rufen Sie uns an: <g1>+{3}</g1>."
],
"Nabízíme dlouhodobý pronájem vozů s flexibilní dobou od {1} měsíců — delší závazek znamená výhodnější měsíční poplatek. Předání a převzetí probíhá na předem dohodnutém místě.": [
"We offer long-term car rental with a flexible term from {1} months — a longer commitment means a more favourable monthly fee. Handover and return take place at a pre-arranged location.",
"Wir bieten Auto-Langzeitmiete mit flexibler Laufzeit ab {1} Monaten — eine längere Bindung bedeutet eine günstigere Monatsgebühr. Übergabe und Rücknahme erfolgen an einem vorab vereinbarten Ort."
],
"Řeknete nám, jaký vůz hledáte, a my vám nabídneme vozy z celého německého trhu: vůz prověříme, na místě zkontrolujeme a poté zajistíme přepravu, registraci a veškeré papírování. Na dovezené vozy platí odpovědnost za vady {1} rok. Pavel Horemuž, dovoz vozů z Německa: <g0>+{2}</g0>.": [
"Tell us what car you are looking for and we will offer you a selection from the entire German market: we vet the car, inspect it on site and then arrange transport, registration and all the paperwork. Imported cars come with a {1}-year liability for defects. Pavel Horemuž, car import from Germany: <g0>+{2}</g0>.",
"Sagen Sie uns, welches Auto Sie suchen, und wir bieten Ihnen eine Auswahl aus dem gesamten deutschen Markt: Wir prüfen das Auto, kontrollieren es vor Ort und organisieren dann Transport, Zulassung und alle Formalitäten. Für importierte Autos gilt eine Mängelhaftung von {1} Jahr. Pavel Horemuž, Autoimport aus Deutschland: <g0>+{2}</g0>."
],
"U ojetých vozů odpovídáme za vady {1} rok od převzetí vozu. Historie každého vozidla je známá a zdokumentovaná a před předáním prochází kontrolou na místě.": [
"For used cars we are liable for defects for {1} year from handover of the car. The history of every vehicle is known and documented, and it undergoes an on-site inspection before handover.",
"Bei Gebrauchtwagen haften wir für Mängel {1} Jahr ab Übergabe des Autos. Die Historie jedes Fahrzeugs ist bekannt und dokumentiert, und vor der Übergabe wird es vor Ort geprüft."
],
"Ano, financování je možné přes partnerskou leasingovou společnost, která vás na požádání kontaktuje přímo.": [
"Yes, financing is possible through a partner leasing company, which will contact you directly on request.",
"Ja, eine Finanzierung ist über eine Partner-Leasinggesellschaft möglich, die Sie auf Wunsch direkt kontaktiert."
],
"Stojí za námi více než {1} prodaných vozů, hodnocení {2} na Googlu a {3} let zkušeností na německém trhu. Každý vůz prověřujeme a kontrolujeme, žádné drobné písmo a žádné skryté náklady — na dovezené vozy platí {4}letá odpovědnost za vady.": [
"We have more than {1} cars sold, a {2} rating on Google and {3} years of experience on the German market behind us. We vet and inspect every car, no small print and no hidden fees — imported cars come with a {4}-year liability for defects.",
"Hinter uns stehen mehr als {1} verkaufte Autos, eine Bewertung von {2} bei Google und {3} Jahre Erfahrung auf dem deutschen Markt. Jedes Auto wird geprüft und kontrolliert, kein Kleingedrucktes und keine versteckten Gebühren — für importierte Autos gilt eine Mängelhaftung von {4} Jahr."
],
