"<g0>Třída C</g0> je ideální pro firemní i soukromé zákazníky: reprezentativní, pohodlná a úsporná. Z německé nabídky ji objednáme s benzínovým, naftovým i plug-in hybridním pohonem a paketem AMG Line.": [
"The <g0>C-Class</g0> is ideal for business and private customers: prestigious, comfortable and economical. From the German market we order it with petrol, diesel or plug-in hybrid drive and with the AMG Line package.",
"Die <g0>C-Klasse</g0> ist ideal für Geschäfts- und Privatkunden: repräsentativ, komfortabel und sparsam. Aus dem deutschen Angebot bestellen wir sie mit Benzin-, Diesel- oder Plug-in-Hybridantrieb und mit AMG Line Paket."
],
"<g0>Třída E</g0> je už desítky let první volbou manažerů. Nová generace je digitálnější, efektivnější a ještě pohodlnější. Z německé nabídky ji objednáme jako benzín, naftu, plug-in hybrid i šestiválec.": [
"The <g0>E-Class</g0> has been the first choice among executive cars for decades. The new generation is more digital, more efficient and even more comfortable. From the German market we order it in petrol, diesel, plug-in hybrid and six-cylinder versions.",
"Die <g0>E-Klasse</g0> ist seit Jahrzehnten erste Wahl unter den Managerautos. Die neue Generation ist digitaler, effizienter und noch komfortabler. Aus dem deutschen Angebot bestellen wir sie als Benziner, Diesel, Plug-in-Hybrid und Sechszylinder."
],
