"Derzeit können Sie aus {1} Versionen wählen: <g0>A{2} Avant e-hybrid quattro</g0> — Plug-in-Hybrid, höhere Ausstattung, ab {3} €/Monat; <g1>A{4} Avant e-hybrid quattro</g1> — Plug-in-Hybrid, Basisausstattung, ab {5} €/Monat."
