"Nové A{1} Avant má plochou, širokou masku Singleframe, úzké LED světlomety a světelný pruh táhnoucí se přes celou zadní část. Svažující se sloupek D a dlouhá linie střechy dodávají sportovní eleganci typickou pro Avanty. Barvy k pronájmu: Daytona šedá perleťová.": [
"The new A{1} Avant has a flat, wide Singleframe grille, slim LED headlights and a full-width light strip at the rear. The sloping D-pillar and long roofline add the sporty elegance typical of Avant models. Colours available for rent: Daytona Grey pearl effect.",
"Der neue A{1} Avant hat einen flachen, breiten Singleframe-Grill, schmale LED-Scheinwerfer und ein durchgehendes Lichtband am Heck. Die geneigte D-Säule und die lange Dachlinie verleihen die für Avant-Modelle typische sportliche Eleganz. Farben zur Miete: Daytonagrau Perleffekt."
],
