"Dlouhodobý pronájem ⟨M1⟩ — zcela nové MPV za měsíční poplatek": [
"⟨M1⟩ long-term rental — a brand-new MPV for a monthly fee",
"⟨M1⟩ Langzeitmiete — ein brandneuer Van gegen Monatsgebühr"
],
"<g0>⟨M1⟩</g0> je oblíbenou volbou v kategorii MPV. V <g1>dlouhodobém pronájmu</g1> s ním můžete jezdit, aniž byste do něj vázali velkou částku: platíte jediný <g2>měsíční poplatek</g2>, servis, daň a pneumatiky zařídíme my. To je podstata <g3>dlouhodobého pronájmu auta</g3>: předvídatelné náklady, nový vůz a žádné starosti s dalším prodejem.": [
"The <g0>⟨M1⟩</g0> is a popular choice in the MPV category. On <g1>long-term rental</g1> you can drive it without tying up a large sum: you pay one <g2>monthly fee</g2>, and we take care of servicing, tax and tyres. That is the essence of <g3>long-term car rental</g3>: predictable costs, a new car and no worries about reselling.",
"Der <g0>⟨M1⟩</g0> ist eine beliebte Wahl in der Van-Klasse. In der <g1>Langzeitmiete</g1> fahren Sie ihn, ohne eine große Summe zu binden: Sie zahlen eine <g2>Monatsgebühr</g2>, Service, Steuer und Reifen erledigen wir. Das ist der Kern der <g3>Auto-Langzeitmiete</g3>: planbare Kosten, ein neues Auto und keine Sorgen um den Wiederverkauf."
],
"Momentálně si můžete pronajmout verzi <g0>{1} TDI SCR Style {2} mm KÜ</g0> (diesel) od {3} €/měs.": [
"You can currently rent the <g0>{1} TDI SCR Style {2} mm KÜ</g0> version (diesel) from {3} €/month.",
"Derzeit können Sie die Version <g0>{1} TDI SCR Style {2} mm KÜ</g0> (Diesel) ab {3} €/Monat mieten."
],
"Pokud nechcete vůz vlastnit, je <g0>dlouhodobý pronájem vozu</g0> nejflexibilnější: žádná akontace, žádné riziko zbytkové hodnoty a na nový model můžete přejít klidně každého půl roku. Pro firmy je nájemné účetním nákladem — podobně jako u <g1>operativního leasingu</g1>, ale bez dlouhého závazku. Pokud byste přesto chtěli vůz vlastnit, prohlédněte si možnosti <g2>leasingu</g2> a <g3>objednávky na míru</g3>. Hledáte jiný model? Podívejte se také na modely <g4>⟨M1⟩</g4> a <g5>⟨M2⟩.{1} Tourer</g5> k pronájmu.": [
"If you don't want to own a car, <g0>long-term car rental</g0> is the most flexible solution: no down payment, no residual value risk, and you can even switch to a new model every six months. For companies the rent is a deductible expense — similar to an <g1>operating lease</g1>, but without a long commitment. If you would still like to own the car, see the options for <g2>leasing</g2> and <g3>custom orders</g3>. Looking for another model? See also the <g4>⟨M1⟩</g4> and <g5>⟨M2⟩.{1} Tourer</g5> models for rent.",
"Wenn Sie kein Auto besitzen möchten, ist die <g0>Auto-Langzeitmiete</g0> die flexibelste Lösung: keine Anzahlung, kein Restwertrisiko, und auf ein neues Modell können Sie sogar alle sechs Monate wechseln. Für Firmen ist die Miete eine abzugsfähige Ausgabe — ähnlich wie beim <g1>Operating Leasing</g1>, aber ohne lange Bindung. Möchten Sie das Auto doch besitzen, sehen Sie sich die Möglichkeiten für <g2>Leasing</g2> und <g3>Bestellung nach Maß</g3> an. Sie suchen ein anderes Modell? Sehen Sie sich auch die Mietmodelle <g4>⟨M1⟩</g4> und <g5>⟨M2⟩.{1} Tourer</g5> an."
],
