"Dovoz vozů z Německa": [
"Car import from Germany",
"Autoimport aus Deutschland"
],
"Ano — na dovezený ojetý vůz platí {1}letá odpovědnost za vady. Povinné ručení a havarijní pojištění si sjednáváte sami u pojišťovny podle vlastního výběru.": [
"Yes — an imported used car comes with a {1}-year liability for defects. You take out compulsory motor liability (MTPL) and comprehensive insurance yourself with an insurer of your choice.",
"Ja — für ein importiertes Gebrauchtfahrzeug gilt eine {1}-jährige Sachmängelhaftung. Kfz-Haftpflicht- und Kaskoversicherung schließen Sie selbst bei einer Versicherung Ihrer Wahl ab."
],
"Proces nákupu — dovoz vozu z Německa krok za krokem": [
"Buying process — importing a car from Germany step by step",
"Kaufablauf — Autoimport aus Deutschland Schritt für Schritt"
],
"Zašleme vám smlouvu a údaje o bankovním účtu. Smlouvu uzavíráte se společností Caradvance GmbH. Poté požadujeme zálohu ve výši {1} % kupní ceny a vzor smlouvy si můžete před podpisem předem prohlédnout.": [
"We send you the contract and the bank account details. You sign the contract with Caradvance GmbH. We then ask for a deposit of {1} % of the purchase price, and you can view a sample contract in advance, before signing.",
"Wir senden Ihnen den Vertrag und die Bankverbindung. Den Vertrag schließen Sie mit der Caradvance GmbH. Danach bitten wir um eine Anzahlung von {1} % des Kaufpreises; den Mustervertrag können Sie vorab, vor der Unterzeichnung, einsehen."
],
"Veškeré úřední vyřizování převezmeme na sebe: DPH a administrativní formality, evidenční kontrola, STK a emise, registr vozidel, registrace — rychle a bez komplikací.": [
"We take over all the official paperwork: VAT and administrative formalities, originality check, technical and emissions inspection, traffic inspectorate, vehicle registration — quickly and without complications.",
"Wir übernehmen alle behördlichen Formalitäten: MwSt. und Verwaltung, Originalitätsprüfung, technische und Abgasuntersuchung, Verkehrsinspektorat, Zulassung — schnell und unkompliziert."
],
"Dovézt vůz z Německa na vlastní pěst je časově náročné a riskantní. Podívejte se vedle sebe: co vás čeká samotné a co za vás převezmeme my — od hledání po…": [
"Importing a car from Germany on your own is time-consuming and risky. See side by side: what awaits you if you do it yourself, and what we take over for you — from…",
"Ein Auto auf eigene Faust aus Deutschland zu importieren ist zeitaufwendig und riskant. Vergleichen Sie: was Sie erwartet, wenn Sie es selbst machen, und was wir Ihnen abnehmen — von…"
],
"Z krátkodobého pohledu se může zdát levnější, ale dovoz vozu ze zahraničí na vlastní pěst je časově náročný a riskantní: cesta, jazyková bariéra, riziko přetočeného tachometru nebo skryté škody a veškeré administrativní a registrační řízení také zůstává na vás. S odborníkem je to vše předvídatelné, zaručené a rychlé.": [
"In the short term it may seem cheaper, but importing a car from abroad on your own is time-consuming and risky: the journey, the language barrier, the risk of a clocked odometer or hidden damage, and all the administrative and registration work stays with you. With an expert, everything is predictable, guaranteed and fast.",
"Kurzfristig mag es günstiger erscheinen, aber ein Auto auf eigene Faust aus dem Ausland zu importieren ist zeitaufwendig und riskant: die Reise, die Sprachbarriere, das Risiko eines manipulierten Tachos oder versteckter Schäden — und die gesamte Verwaltung und Zulassung bleibt bei Ihnen. Mit einem Experten ist alles planbar, garantiert und schnell."
],
"Vše z jedné ruky: hledání na celém německém trhu, mezinárodní prověření, kontrola na místě, vyjednávání o ceně, doprava s pojištěním, DPH a administrativní formality, evidenční kontrola, STK a emise, registrace a zápis vozu na vaše jméno.": [
"Everything from a single source: search across the entire German market, international vetting, on-site inspection, price negotiation, insured transport, VAT and administrative formalities, originality check, technical inspection, vehicle registration and putting it on the road in your name.",
"Alles aus einer Hand: Suche auf dem gesamten deutschen Markt, internationale Prüfung, Kontrolle vor Ort, Preisverhandlung, versicherter Transport, MwSt. und Verwaltungsformalitäten, Originalitätsprüfung, technische Prüfung, Zulassung und Inbetriebnahme auf Ihren Namen."
],
"Zpravidla ano: stojí za nimi silnější servisní kultura, kvalitní silnice a disciplinovaná údržba. Přesto každý vůz prověřujeme a na místě prohlížíme — za skutečný stav a věrohodný nájezd také odpovídáme.": [
"Usually yes: they are backed by a stronger service culture, good roads and disciplined maintenance. Regardless, we vet and inspect every car on site — and we also stand behind its actual condition and genuine mileage.",
"Meist ja: Dahinter stehen eine stärkere Servicekultur, gute Straßen und disziplinierte Wartung. Unabhängig davon prüfen und kontrollieren wir jedes Auto vor Ort — und haften auch für den tatsächlichen Zustand und den echten Kilometerstand."
],
"Ano. Vůz kupujete od společnosti Caradvance GmbH, která vám ho i doveze; na základě vaší plné moci vám pomůžeme s registrací, STK a emisemi i zápisem do registru. Vy si pouze převezmete vůz zaregistrovaný na vaše jméno a připravený k provozu.": [
"Yes. You buy the car from Caradvance GmbH, which also delivers it to you; on the basis of your power of attorney we help you with vehicle registration, the technical and emissions inspection and the registration records. You simply take over the car registered in your name.",
"Ja. Sie kaufen das Auto von der Caradvance GmbH, die es Ihnen auch liefert; auf Grundlage Ihrer Vollmacht helfen wir Ihnen bei der Zulassung, der technischen und Abgasuntersuchung sowie der Registrierung. Sie übernehmen nur noch das auf Ihren Namen zugelassene Auto."
],
