"Časté dotazy k dlouhodobému pronájmu (od {1} měsíců)": [
"Frequently asked questions about long-term rental (from {1} months)",
"Häufige Fragen zur Langzeitmiete (ab {1} Monaten)"
],
"Časté dotazy k dlouhodobému pronájmu (minimálně {1} měsíců): kauce a podmínky, náklady all-inclusive (servis, daň, pneumatiky), výběr vozu, firemní pronájem a celý proces.": [
"Frequently asked questions about long-term rental (minimum {1} months): deposit and conditions, all-inclusive costs (servicing, tax, tyres), choosing a car, company rental and the whole process.",
"Häufige Fragen zur Langzeitmiete (mindestens {1} Monate): Kaution und Bedingungen, All-inclusive-Kosten (Service, Steuer, Reifen), Autowahl, Firmenmiete und der gesamte Ablauf."
],
"U nás si můžete dlouhodobě pronajmout nový nebo málo ježděný německý prémiový vůz v bezvadném stavu — ⟨M1⟩, ⟨M2⟩, ⟨M3⟩ a další — minimálně na {1} měsíců (denní ani týdenní pronájem nenabízíme). Servis, daň a letní i zimní pneumatiky hradíme my a kauce je výhodnější než průměr trhu, takže vy v podstatě jen jezdíte.": [
"With us you can rent a new or low-mileage German premium car in flawless condition long term — ⟨M1⟩, ⟨M2⟩, ⟨M3⟩ and others — for at least {1} months (we do not offer daily or weekly rental). We pay for servicing, tax and summer and winter tyres, and the deposit is better than the market average, so you basically just drive.",
"Bei uns können Sie ein neues oder wenig gefahrenes deutsches Premium-Auto in einwandfreiem Zustand langfristig mieten — ⟨M1⟩, ⟨M2⟩, ⟨M3⟩ und weitere — für mindestens {1} Monate (Tages- oder Wochenmiete bieten wir nicht an). Service, Steuer sowie Sommer- und Winterreifen übernehmen wir, und die Kaution ist günstiger als der Marktdurchschnitt — Sie fahren im Grunde nur."
],
