"Pronájem ⟨M1⟩ třída C Limuzína": [
"⟨M1⟩ C-Class Saloon rental",
"⟨M1⟩ C-Klasse Limousine mieten"
],
"Kolik stojí pronájem ⟨M1⟩ třída C Limuzína?": [
"How much does it cost to rent the ⟨M1⟩ C-Class Saloon?",
"Was kostet die Miete der ⟨M1⟩ C-Klasse Limousine?"
],
"Měsíční poplatek zahrnuje užívání zcela nového vozu ⟨M1⟩ třída C Limuzína s dohodnutým limitem kilometrů; servis, daň a sadu letních a zimních pneumatik hradíme my. Přesné podmínky předem písemně uvedeme v nabídce.": [
"The monthly fee covers the use of a brand-new ⟨M1⟩ C-Class Saloon with the agreed mileage limit; we pay for servicing, tax and a set of summer and winter tyres. We state the exact terms in writing in the offer in advance.",
"Die Monatsrate umfasst die Nutzung einer brandneuen ⟨M1⟩ C-Klasse Limousine mit dem vereinbarten Kilometerlimit; Service, Steuer und einen Satz Sommer- und Winterreifen übernehmen wir. Die genauen Bedingungen nennen wir Ihnen vorab schriftlich im Angebot."
],
"{1} ks ⟨M1⟩ třída C Limuzína ihned k dispozici; další vozy: listopad: {2} ks, prosinec: {3} ks. Předáváme zcela nový vůz s {4} km.": [
"{1} × ⟨M1⟩ C-Class Saloon available immediately; more cars: November: {2}, December: {3}. We hand over a brand-new car with {4} km.",
"{1} × ⟨M1⟩ C-Klasse Limousine sofort verfügbar; weitere Autos: November: {2}, Dezember: {3}. Wir übergeben ein brandneues Auto mit {4} km."
],
"Ano, dlouhodobý pronájem ⟨M1⟩ třída C Limuzína je dostupný pro soukromé osoby i firmy. Pro firmu je nájemné daňově uznatelným nákladem.": [
"Yes, long-term rental of the ⟨M1⟩ C-Class Saloon is available to both private individuals and companies. For a company, the rent is a tax-deductible expense.",
"Ja, die Langzeitmiete der ⟨M1⟩ C-Klasse Limousine steht Privatpersonen und Firmen offen. Für Firmen ist die Miete steuerlich absetzbar."
],
"⟨M1⟩ třída C Limuzína": [
"⟨M1⟩ C-Class Saloon",
"⟨M1⟩ C-Klasse Limousine"
],
