"Nový vůz (do {1} měsíců od první registrace nebo s nejvýše {2} km) se v rámci EU vždy daní ve státě kupujícího – v Česku {3} % DPH. Caradvance GmbH vám vystaví fakturu bez německé DPH a českou DPH zaplatíte v Česku: soukromá osoba ji přizná a zaplatí na svém finančním úřadě, firma ji uvede ve svém daňovém přiznání. Postup vám při objednávce vysvětlíme. Výhodou je německá cena a výběr, ne nižší DPH.": [
"A new car (up to {1} months from first registration or with no more than {2} km) is always taxed within the EU in the buyer's country – in the Czech Republic at {3} % VAT. Caradvance GmbH issues you an invoice without German VAT, and you pay the Czech VAT in the Czech Republic: a private individual declares and pays it at their tax office, a company includes it in its tax return. We will explain the procedure when you order. The advantage is the German price and choice, not lower VAT.",
"Ein Neuwagen (bis {1} Monate nach Erstzulassung oder mit höchstens {2} km) wird in der EU immer im Land des Käufers besteuert – in Tschechien mit {3} % MwSt. Die Caradvance GmbH stellt Ihnen eine Rechnung ohne deutsche MwSt. aus, und die tschechische MwSt. zahlen Sie in Tschechien: Eine Privatperson meldet und zahlt sie bei ihrem Finanzamt, eine Firma gibt sie in ihrer Steuererklärung an. Den Ablauf erklären wir Ihnen bei der Bestellung. Der Vorteil ist der deutsche Preis und die Auswahl, nicht eine niedrigere MwSt."
],
