"Co je emisní poplatek (dříve „ekologická daň“)?": [
"What is the emission fee (formerly the “eco tax”)?",
"Was ist die Emissionsgebühr (früher „Ökosteuer“)?"
],
"Emisní poplatek podle zákona č. {1}/{2} Sb. se platí u osobních aut (M{3}) a lehkých užitkových vozů (N{4}) při první registraci v ČR, při změně vlastníka nebo provozovatele. Výše: Euro {5} — {6} Kč, Euro {7} — {8} Kč, Euro {9} nebo bez normy — {10} Kč. Za jedno vozidlo se platí jen jednou: pokud už byl zaplacen (nebo dřívější ekopoplatek podle zákona o odpadech), znovu se neplatí. Osvobození upravuje § {11} zákona.": [
"The emission fee under Act No. {1}/{2} Coll. is paid for passenger cars (M{3}) and light commercial vehicles (N{4}) on first registration in the Czech Republic and on a change of owner or keeper. Amount: Euro {5} — {6} Kč, Euro {7} — {8} Kč, Euro {9} or no standard — {10} Kč. It is paid only once per vehicle: if it has already been paid (or the earlier eco fee under the Waste Act), it is not paid again. Exemptions are set out in § {11} of the Act.",
"Die Emissionsgebühr nach Gesetz Nr. {1}/{2} Slg. wird für Pkw (M{3}) und leichte Nutzfahrzeuge (N{4}) bei der Erstzulassung in Tschechien sowie bei einem Eigentümer- oder Halterwechsel gezahlt. Höhe: Euro {5} — {6} Kč, Euro {7} — {8} Kč, Euro {9} oder ohne Norm — {10} Kč. Pro Fahrzeug wird sie nur einmal gezahlt: Wurde sie bereits entrichtet (oder die frühere Ökogebühr nach dem Abfallgesetz), fällt sie nicht erneut an. Befreiungen regelt § {11} des Gesetzes."
],
"Platí se poplatek za elektromobil?": [
"Is a fee payable for an electric car?",
"Fällt für ein Elektroauto eine Gebühr an?"
],
"Pokud se elektromobilu (nebo vozu na vodík či plug-in hybridu do {1} g CO₂/km) při registraci současně přidělí registrační značka EL, správní poplatek se neplatí. Při přepisu vozidla, které už značku EL má, se platí běžných {2} Kč. Emisní poplatek se elektromobilů netýká.": [
"If an electric car (or a hydrogen car or a plug-in hybrid up to {1} g CO₂/km) is assigned an EL registration plate at the same time as registration, no administrative fee is paid. When transferring a vehicle that already has an EL plate, the usual {2} Kč is paid. The emission fee does not apply to electric cars.",
"Wird einem Elektroauto (oder einem Wasserstoffauto bzw. einem Plug-in-Hybrid bis {1} g CO₂/km) bei der Zulassung gleichzeitig ein EL-Kennzeichen zugeteilt, wird keine Verwaltungsgebühr gezahlt. Bei der Umschreibung eines Fahrzeugs, das bereits ein EL-Kennzeichen hat, werden die üblichen {2} Kč fällig. Die Emissionsgebühr betrifft Elektroautos nicht."
],
"Kde najdu emisní normu vozidla?": [
"Where can I find the vehicle's emission standard?",
"Wo finde ich die Abgasnorm des Fahrzeugs?"
],
"V osvědčení o registraci (technickém průkazu), v COC listu nebo v datech výrobce. Pokud normu neznáte, kalkulačka ji odhadne podle data první registrace — rozhodující je však údaj v dokladech vozidla.": [
"In the registration certificate (vehicle documents), in the COC certificate or in the manufacturer's data. If you don't know the standard, the calculator estimates it from the date of first registration — but the figure in the vehicle documents is decisive.",
"In der Zulassungsbescheinigung (Fahrzeugpapiere), in der COC-Bescheinigung oder in den Herstellerdaten. Kennen Sie die Norm nicht, schätzt der Rechner sie anhand des Erstzulassungsdatums — maßgeblich ist jedoch die Angabe in den Fahrzeugpapieren."
],
"Co dalšího je potřeba zaplatit?": [
"What else needs to be paid?",
"Was muss sonst noch bezahlt werden?"
],
"Evidenční kontrolu ve stanici technické kontroly (cena podle ceníku stanice), u dovezeného vozu případně technickou prohlídku, povinné ručení (pojištění odpovědnosti) a při převozu vozidla případně převozní značky. Tyto položky kalkulačka nezahrnuje.": [
"The registration check at a technical inspection station (price according to the station's price list), for an imported car possibly a technical inspection, compulsory motor liability insurance and, when transferring the vehicle, possibly temporary transfer plates. The calculator does not include these items.",
"Die Evidenzkontrolle an einer Prüfstelle (Preis laut Preisliste der Station), bei einem importierten Auto ggf. eine technische Prüfung, die Kfz-Haftpflichtversicherung und bei der Überführung ggf. Überführungskennzeichen. Diese Posten enthält der Rechner nicht."
],
"Platí se při dovozu ojetého auta z Německa česká DPH?": [
"Is Czech VAT payable when importing a used car from Germany?",
"Fällt beim Import eines Gebrauchtwagens aus Deutschland tschechische MwSt. an?"
],
"U ojetého auta koupeného od obchodníka z EU ve zvláštním režimu (zdanění přirážky) česká DPH zpravidla nevzniká. Auto mladší než šest měsíců nebo s nájezdem do {1} km se však považuje za nový dopravní prostředek a DPH se z něj platí v ČR.": [
"For a used car bought from an EU dealer under the special scheme (margin taxation), Czech VAT usually does not arise. However, a car less than six months old or with up to {1} km is considered a new means of transport and VAT on it is paid in the Czech Republic.",
"Bei einem Gebrauchtwagen, der von einem EU-Händler im Sonderregime (Differenzbesteuerung) gekauft wurde, entsteht in der Regel keine tschechische MwSt. Ein Auto, das jünger als sechs Monate ist oder bis zu {1} km gelaufen hat, gilt jedoch als neues Fahrzeug, und die MwSt. wird in Tschechien gezahlt."
],
