"Der deutsche Listenpreis des ⟨M1⟩ {1}er Touring beginnt bei {2} € ohne MwSt. (ca. {3} Kč); der Endpreis hängt von Motor und Ausstattung ab. Privatpersonen wie Firmen können ihn über die Caradvance GmbH bei München (Geretsried) bestellen — für ein genaues Preisangebot kontaktieren Sie uns."
