"⟨M1⟩ configurator —<x0/><g1>build it, we'll order it at the German price</g1>",
"⟨M1⟩ Konfigurator —<x0/><g1>stellen Sie ihn zusammen, wir bestellen ihn zum deutschen Preis</g1>"
