"V CarAdvance začíná čistý měsíční poplatek za nová auta od {1} Kč/měs. (⟨M1⟩), prémiová střední třída (⟨M2⟩, ⟨M3⟩, ⟨M4⟩) stojí {4}–{5} Kč/měs., velká SUV (⟨M5⟩, ⟨M6⟩) od {7} Kč/měs. Ceny platí podle auta pro limit {8}–{9} km měsíčně a dobu {10} měsíců.": [
"At CarAdvance the net monthly fee for new cars starts from {1} Kč/month (⟨M1⟩), the premium mid-size class (⟨M2⟩, ⟨M3⟩, ⟨M4⟩) costs {4}–{5} Kč/month, large SUVs (⟨M5⟩, ⟨M6⟩) from {7} Kč/month. Prices apply, depending on the car, to a limit of {8}–{9} km per month and a term of {10} months.",
"Bei CarAdvance beginnt die Netto-Monatsgebühr für Neuwagen ab {1} Kč/Monat (⟨M1⟩), die Premium-Mittelklasse (⟨M2⟩, ⟨M3⟩, ⟨M4⟩) kostet {4}–{5} Kč/Monat, große SUVs (⟨M5⟩, ⟨M6⟩) ab {7} Kč/Monat. Die Preise gelten je nach Auto für ein Limit von {8}–{9} km pro Monat und eine Laufzeit von {10} Monaten."
],
