"Celý proces: přeprava, daňové a administrativní vyřízení, evidenční kontrola, STK, registrace dovezeného vozu, úřad, uvedení do provozu — vše vyřídíme my.": [
"The whole process: transport, tax and administrative formalities, registration check, technical inspection, registration of the imported vehicle, the authorities, putting it into service — we handle everything.",
"Der gesamte Ablauf: Transport, steuerliche und administrative Abwicklung, Evidenzkontrolle, technische Prüfung, Zulassung des importierten Fahrzeugs, Behörden, Inbetriebnahme — wir erledigen alles."
],
"Podle vybraného vozu obvykle {1}–{2} dní: po vyhledání na německém trhu a kontrole vůz přepravíme, provedeme registraci a uvedení do provozu v Česku.": [
"Depending on the chosen car, usually {1}–{2} days: after searching the German market and the inspection, we transport the car and carry out registration and putting into service in the Czech Republic.",
"Je nach gewähltem Auto in der Regel {1}–{2} Tage: Nach der Suche auf dem deutschen Markt und der Prüfung transportieren wir das Auto und übernehmen Zulassung und Inbetriebnahme in Tschechien."
],
"Kromě kupní ceny přeprava, správní poplatek za registraci ({1} Kč, se značkou EL {2} Kč), u vozů Euro {3} a starších emisní poplatek, evidenční kontrola (podle ceníku stanice), STK při registraci a SPZ. Úřední položky ukáže naše kalkulačka poplatků za registraci v jedné částce; kompletní položkovou nabídku zpracujeme my.": [
"Besides the purchase price: transport, the administrative registration fee ({1} Kč, with an EL plate {2} Kč), for Euro {3} and older cars the emission fee, the registration check (according to the station's price list), the technical inspection at registration and the number plate. Our registration fee calculator shows the official items as one amount; we prepare the complete itemised offer.",
"Neben dem Kaufpreis: Transport, die Verwaltungsgebühr für die Zulassung ({1} Kč, mit EL-Kennzeichen {2} Kč), bei Autos mit Euro {3} und älter die Emissionsgebühr, die Evidenzkontrolle (laut Preisliste der Station), die technische Prüfung bei der Zulassung und das Kennzeichen. Unser Zulassungsgebührenrechner zeigt die amtlichen Posten in einer Summe; das vollständige, aufgeschlüsselte Angebot erstellen wir."
],
"Ano. Prodávajícím je vždy Caradvance GmbH a fakturu vystaví ona: při doručení až k vám s {1} % českou DPH; u ojetého vozu, který si osobně převezmete v Německu a dopravu si zajistíte sami, s {2} % německou DPH; firmě s DIČ bez DPH (dodání v rámci EU). Zavolejte nám a společně najdeme nejvýhodnější variantu.": [
"Yes. The seller is always Caradvance GmbH, and it issues the invoice: with delivery to you, with {1} % Czech VAT; for a used car that you collect personally in Germany and transport yourself, with {2} % German VAT; to a company with a VAT ID, without VAT (intra-EU supply). Call us and together we will find the most advantageous option.",
"Ja. Verkäufer ist immer die Caradvance GmbH, und sie stellt die Rechnung aus: bei Lieferung zu Ihnen mit {1} % tschechischer MwSt.; bei einem Gebrauchtwagen, den Sie persönlich in Deutschland abholen und selbst transportieren, mit {2} % deutscher MwSt.; an eine Firma mit USt-IdNr. ohne MwSt. (innergemeinschaftliche Lieferung). Rufen Sie uns an, gemeinsam finden wir die günstigste Variante."
],
"Kolik stojí registrace dovezeného auta v roce {1}?": [
"How much does registering an imported car cost in {1}?",
"Was kostet die Zulassung eines importierten Autos im Jahr {1}?"
],
"Správní poplatek za zápis osobního auta do registru silničních vozidel je {1} Kč. Pokud se současně přiděluje registrační značka EL (elektromobil, vodík, plug-in hybrid do {2} g CO₂/km), poplatek se neplatí. U dovezeného auta s normou Euro {3} a starší se platí ještě emisní poplatek {4} až {5} Kč; Euro {6} a novější je bez emisního poplatku.": [
"The administrative fee for entering a passenger car in the road vehicle register is {1} Kč. If an EL registration plate is assigned at the same time (electric car, hydrogen, plug-in hybrid up to {2} g CO₂/km), no fee is paid. For an imported car with Euro {3} or older, an emission fee of {4} to {5} Kč is also payable; Euro {6} and newer are exempt from the emission fee.",
"Die Verwaltungsgebühr für die Eintragung eines Pkw ins Register der Straßenfahrzeuge beträgt {1} Kč. Wird gleichzeitig ein EL-Kennzeichen zugeteilt (Elektroauto, Wasserstoff, Plug-in-Hybrid bis {2} g CO₂/km), entfällt die Gebühr. Bei einem importierten Auto mit Euro {3} und älter kommt noch eine Emissionsgebühr von {4} bis {5} Kč hinzu; Euro {6} und neuer sind von der Emissionsgebühr befreit."
],
