"<g0>Kalkulačka má informativní charakter.</g0> Výši poplatků vždy určí registr vozidel. Nezahrnuje evidenční kontrolu a technickou prohlídku, povinné ručení ani převozní značky. Zdroj: <g1>zákon č. {1}/{2} Sb., položka {3}</g1> a <g2>zákon č. {4}/{5} Sb.</g2>": [
"<g0>The calculator is for information only.</g0> The amount of the fees is always determined by the vehicle register. It does not include the registration check and technical inspection, compulsory motor liability insurance or transfer plates. Source: <g1>Act No. {1}/{2} Coll., item {3}</g1> and <g2>Act No. {4}/{5} Coll.</g2>",
"<g0>Der Rechner dient nur zur Information.</g0> Die Höhe der Gebühren bestimmt immer das Fahrzeugregister. Nicht enthalten sind Evidenzkontrolle und technische Prüfung, Kfz-Haftpflichtversicherung sowie Überführungskennzeichen. Quelle: <g1>Gesetz Nr. {1}/{2} Slg., Posten {3}</g1> und <g2>Gesetz Nr. {4}/{5} Slg.</g2>"
],
