"Kauci — stejně jako nájemné — platíte pronajímateli, německé společnosti Caradvance GmbH. Mr. Job SK s.r.o. je obchodním zprostředkovatelem Caradvance GmbH pro Česko a není pronajímatelem.": [
"You pay the deposit — just like the rent — to the lessor, the German company Caradvance GmbH. Mr. Job SK s.r.o. is the commercial agent of Caradvance GmbH for the Czech Republic and is not the lessor.",
"Die Kaution zahlen Sie — genau wie die Miete — an den Vermieter, die deutsche Caradvance GmbH. Die Mr. Job SK s.r.o. ist Handelsvermittler der Caradvance GmbH für Tschechien und nicht der Vermieter."
],
"Dlouhodobý pronájem nabízíme především firmám – plátcům DPH. Pro soukromé osoby připravíme individuální nabídku – zavolejte na +{1} nebo napište na info@caradvance.cz.": [
"We offer long-term rental primarily to VAT-registered companies. For private individuals we prepare an individual offer – call +{1} or write to info@caradvance.cz.",
"Die Langzeitmiete bieten wir vor allem umsatzsteuerpflichtigen Firmen an. Für Privatpersonen erstellen wir ein individuelles Angebot – rufen Sie +{1} an oder schreiben Sie an info@caradvance.cz."
],
"Všechny důležité body nájemní smlouvy — kauci, limit kilometrů, pojištění a spoluúčast, postup při škodě, pneumatiky, pokuty, používání v zahraničí a vrácení vozu — jsme přehledně shrnuli na stránce Podmínky pronájmu a kauce (caradvance.cz/pronajem/podminky-a-kauce/).": [
"We have clearly summarised all the important points of the rental contract — deposit, mileage limit, insurance and excess, what to do in case of damage, tyres, fines, use abroad and returning the car — on the Rental terms and deposit page (caradvance.cz/pronajem/podminky-a-kauce/).",
"Alle wichtigen Punkte des Mietvertrags — Kaution, Kilometerlimit, Versicherung und Selbstbeteiligung, Vorgehen im Schadensfall, Reifen, Strafen, Nutzung im Ausland und Rückgabe — haben wir übersichtlich auf der Seite Mietbedingungen und Kaution (caradvance.cz/pronajem/podminky-a-kauce/) zusammengefasst."
],
