"<g0>Dlouhodobý pronájem auta</g0> zcela nových aut ({1} km) u nás začíná <g1>od {2} Kč/měs.</g1> (bez DPH), podle auta s limitem <g2>{3}–{4} km měsíčně</g2> a dobou <g3>{5} měsíců</g3>. Prémiová SUV začínají na {6}–{7} Kč, business limuzíny a kombi na {8}–{9} Kč, velká SUV na {10} Kč. Servis, daň a pneumatiky jsou v ceně; kauce je {11}–{12} € a vrací se. Aktuální poplatek každého modelu najdeš mezi <g4>našimi auty k pronájmu</g4>.": [
"<g0>Long-term car rental</g0> of brand-new cars ({1} km) starts with us <g1>from {2} Kč/month</g1> (excl. VAT), depending on the car with a limit of <g2>{3}–{4} km per month</g2> and a term of <g3>{5} months</g3>. Premium SUVs start at {6}–{7} Kč, business saloons and estates at {8}–{9} Kč, large SUVs at {10} Kč. Servicing, tax and tyres are included; the deposit is {11}–{12} € and is refundable. You will find the current fee for each model among <g4>our cars for rent</g4>.",
"Die <g0>Auto-Langzeitmiete</g0> brandneuer Autos ({1} km) beginnt bei uns <g1>ab {2} Kč/Monat</g1> (ohne MwSt.), je nach Auto mit einem Limit von <g2>{3}–{4} km pro Monat</g2> und einer Laufzeit von <g3>{5} Monaten</g3>. Premium-SUVs beginnen bei {6}–{7} Kč, Business-Limousinen und Kombis bei {8}–{9} Kč, große SUVs bei {10} Kč. Service, Steuer und Reifen sind inklusive; die Kaution beträgt {11}–{12} € und wird erstattet. Die aktuelle Gebühr jedes Modells finden Sie unter <g4>unseren Mietautos</g4>."
],
