"<g0>Pronájem ⟨M1⟩</g0> je nejjednodušší cesta ke zcela novému vozu: v <g1>dlouhodobém pronájmu</g1> s ním můžete jezdit od {1} Kč/měs., s limitem {2}–{3} km/měs. a dobou pronájmu {4} měsíců. Aktuálně si můžete vybrat z {5} vozů ⟨M2⟩ ({6} k dispozici ihned), ve verzích {7} eTSI DSG, {8} TDI DSG, {9} TSI {10}MOTION DSG, {11} TDI {12}MOTION DSG. Jednorázová vratná <g2>kauce</g2> od {13} €; servis, daň i letní a zimní pneumatiky hradíme my. Vůz nemusíte vlastnit: na konci pronájmu ho jednoduše vrátíte nebo přejdete na nový model.": [
"<g0>Renting the ⟨M1⟩</g0> is the easiest way to a brand-new car: on <g1>long-term rental</g1> you can drive it from {1} Kč/month, with a limit of {2}–{3} km/month and a rental period of {4} months. You can currently choose from {5} ⟨M2⟩ cars ({6} available immediately), in the versions {7} eTSI DSG, {8} TDI DSG, {9} TSI {10}MOTION DSG, {11} TDI {12}MOTION DSG. One-off refundable <g2>deposit</g2> from {13} €; we cover servicing, tax and both summer and winter tyres. You don't have to own the car: at the end of the rental you simply return it or switch to a new model.",
"<g0>Den ⟨M1⟩ mieten</g0> ist der einfachste Weg zu einem brandneuen Auto: In der <g1>Langzeitmiete</g1> fahren Sie ihn ab {1} Kč/Monat, mit einem Limit von {2}–{3} km/Monat und einer Mietdauer von {4} Monaten. Derzeit können Sie aus {5} ⟨M2⟩ Autos wählen ({6} sofort verfügbar), in den Versionen {7} eTSI DSG, {8} TDI DSG, {9} TSI {10}MOTION DSG, {11} TDI {12}MOTION DSG. Einmalige rückzahlbare <g2>Kaution</g2> ab {13} €; Service, Steuer sowie Sommer- und Winterreifen übernehmen wir. Sie müssen das Auto nicht besitzen: Am Ende der Miete geben Sie es einfach zurück oder steigen auf ein neues Modell um."
],
